  "cn-296": {"name":"Stage Manager","summary":"Coordinates stage equipment, lighting, sound, and performers to keep a show running safely.","tasks":["Plan stage technical work","Coordinate staff roles","Manage actors' entrance timing","Check stage safety"],"msActions":["Join the staff preparing the stage for a school festival or talent show","Watch a play or musical and record how the lighting and stage sets change","Build and decorate a small stage model from a shoebox"]},
