  "cn-467": {"name":"Medical Information Systems Developer","summary":"Plans and develops medical information systems that manage a hospital's patient and administrative data.","tasks":["Plan and develop medical information systems","Design systems to manage patient and administrative data","Check system equipment and fix errors"],"msActions":["Make a simple appointment booking program with block coding","Try a hospital app or self-service check-in kiosk and list what is easy and hard about it","Research how to keep personal information safe and share it with friends"]},
  "cn-469": {"name":"CRM (Customer Relationship Management) Specialist","summary":"Analyzes and combines a company's customer data and designs information systems to manage customers well.","tasks":["Analyze and combine customer data","Design customer management systems","Improve and update systems","Train users and give technical advice"],"msActions":["Survey classmates about their favorite snacks and organize the results in a table and graph","Watch how online shops show recommended products and think about why","Follow a basic programming course on a coding learning site"]},
  "cn-470": {"name":"E-commerce Specialist","summary":"Plans and runs e-commerce systems where products and services can be bought and sold online.","tasks":["Plan e-commerce business","Build and run online shop systems","Set marketing and promotion strategy","Review related laws"],"msActions":["Draw the ordering steps of a shopping app you often use","Make promotional text and a poster for something to sell at a school festival","Join a youth economics lecture or economics camp"]},
  "cn-474": {"name":"IT Technical Sales Representative","summary":"Uses expert knowledge of IT products to introduce and sell hardware and software that fit each customer.","tasks":["Advise on and recommend IT products","Handle sales contracts and after-sales service","Write business plans","Plan seminars and exhibitions"],"msActions":["Pick one new electronic device and present its strengths in one minute","Clip one IT news article a week","Ask your family what features they need in a new device and help find a suitable product"]},
  "cn-475": {"name":"IT Instructor","summary":"Teaches students how to use computer programs and IT theory, and also gives career advice.","tasks":["Teach IT theory and hands-on practice","Create course materials","Give job and career advice in the IT field"],"msActions":["Explain what you learned on a coding site to a friend","Make a guide with screenshots showing how to use a program you often use","Read IT news and sum up a new technology you learned about in one line"]},
  "cn-476": {"name":"Radio Frequency (RF) Engineer","summary":"Researches and designs wireless communication equipment that uses radio frequencies, and tests its performance.","tasks":["Plan and design wireless communication equipment","Analyze market and technology trends","Test performance and quality","Analyze causes of defects"],"msActions":["Build a radio kit and learn how radio waves turn into sound","Record how the phone Wi-Fi signal strength differs from place to place","Visit a radio museum or science museum to see communication exhibits"]},
