  "cn-795": {"name":"Hotel Manager","summary":"Plans and manages staff so that a hotel's many operations, such as rooms, restaurants, and banquets, run smoothly.","tasks":["Plan and coordinate hotel operations","Train and manage staff","Set business strategy","Handle guest complaints"],"msActions":["Take on the role of guest guide at a school event","Watch what the lodging staff do on a family trip","Practice simple English guide phrases and act out welcoming a foreign guest"]},
  "cn-911": {"name":"Lighting Technician","summary":"Sets up and controls lighting equipment at performances, film sets, and broadcasts to bring out the mood of a scene.","tasks":["Make the lighting plan","Set up and place lighting equipment","Adjust brightness, color, and timing"],"msActions":["Decorate a puppet show stage with a flashlight and colored cellophane","Observe the direction and color of light in a favorite movie scene","Help the teacher in charge of lighting at a school show or festival"]},
