  "cn-917": {"name":"Record Producer","summary":"Analyzes the music market and listeners' needs to plan an album, and leads it from production to promotion.","tasks":["Research the music market and consumers","Plan the album theme and choose participants","Oversee the production process","Set promotion and sales strategy"],"msActions":["Analyze the album introduction and track list of a favorite singer","Survey friends about their music tastes and show the results in a graph","Choose an imaginary album theme and make a track list and cover ideas"]},
