  "cn-928": {"name":"Sales Representative","summary":"Meets customers, introduces and persuades them about products and services, and signs sales contracts.","tasks":["Find and advise customers","Explain products and persuade","Close contracts and take payment","Follow up after purchase"],"msActions":["Introduce and sell items at a school bazaar","Pick a favorite item and give a one-minute talk persuading a friend of its strengths","Watch how staff serve customers in a shop or store"]},
  "cn-929": {"name":"Craftsperson","summary":"Makes craft items by hand and with tools from materials such as wood, stone, clay, metal, and paper.","tasks":["Design craft items","Process materials and make items","Make traditional crafts"],"msActions":["Make a small everyday item from clay or traditional Korean paper","Observe traditional crafts at a museum and research their materials and methods","Try woodworking or pottery at a craft experience workshop"]},
  "cn-933": {"name":"Sociology Researcher","summary":"Investigates and analyzes social phenomena and problems with data, and finds policy options to solve them.","tasks":["Collect and analyze data on social phenomena","Study the causes of social problems","Propose policy options","Write research reports"],"msActions":["Pick a social problem you care about from the news and sum up its causes and solutions","Run a simple survey of classmates and show the results in a graph","Read an introductory sociology book for teens and keep a reading log"]},
  "cn-1259": {"name":"Magician","summary":"Creates amazing magic tricks with sleight of hand and magic props, and performs them for audiences on stage.","tasks":["Researching new magic techniques","Making magic props","Planning and running stage shows","Teaching magic"],"msActions":["Learn one card or coin trick and perform it for your family","Join a magic activity program at a youth center","Watch a magic show you like and note how it is staged (music, lighting, words)"]},
  "cn-1276": {"name":"Party Planner","summary":"Plans the party a client wants and takes charge of everything from preparation to the event and wrap-up.","tasks":["Discussing the party theme and layout","Preparing decorations, food, and entertainment","Running the party on the day","Writing a results report"],"msActions":["Plan a family birthday party yourself, from the theme to the decorations","Join the class event committee and share out the roles","Draw party decoration ideas using colors and space layouts"]},
