  "cn-1440": {"name":"General Practitioner","summary":"Examines and tests patients, diagnoses and treats illnesses, and prescribes medicine.","tasks":["Examining patients and doing medical tests","Diagnosing and treating diseases","Prescribing medicine","Giving vaccinations and health advice"],"msActions":["Take a first aid class","Join a job experience program at a hospital or public health center","Pick one organ in the body and research what it does"]},
  "cn-1441": {"name":"Writer","summary":"Creates written works such as novels, poems, children's stories, screenplays, and drama scripts.","tasks":["Creating literary works","Writing screenplays and scripts","Collecting and analyzing material","Adapting works"],"msActions":["Write a short diary or observation note every day","Imagine and write what happens after the end of a novel you like","Enter a writing contest at or outside your school"]},
