  "cn-113": {"name":"Electrician","summary":"Installs and repairs power systems so electricity reaches homes, shops, and factories safely.","tasks":["Install wiring and equipment","Maintain power facilities","Check with measuring instruments"],"msActions":["Join an electricity-related experience program","Make a simple circuit with a battery and a light bulb","Research electrical safety rules and make a poster"]},
  "cn-119": {"name":"Electronics Engineer","summary":"Designs and develops electronic products and manages and supervises production.","tasks":["Design and develop electronic products","Test product performance","Manage and supervise production"],"msActions":["Build an electronic kit to learn how a device works","Join a career experience program in electronics engineering","Read the manual of a broken electronic product and try to understand how it is built"]},
  "cn-120": {"name":"Electronic Equipment Installer and Repairer","summary":"Installs electronic equipment such as medical devices and card readers, and fixes it when it breaks.","tasks":["Install electronic equipment","Check and repair faults","Explain how to use the equipment"],"msActions":["Look up materials about electronics fairs or experience events","Safely take apart a broken device and learn the names of its parts","Build an electronic kit to understand circuits"]},
  "cn-121": {"name":"Telephone Installer and Repairer","summary":"Moves and connects telephones at new locations and repairs broken phones and parts.","tasks":["Move and connect telephone lines","Analyze the cause of faults","Repair and replace parts"],"msActions":["Research how landline phones and the internet reach your home","Build an electronic kit or a simple circuit","Safely take apart a broken electronic device and learn the names of its parts"]},
  "cn-122": {"name":"Precision Instrument Maker","summary":"Makes precision instruments such as microscopes and cameras from small parts like sensors and control units.","tasks":["Make and assemble parts","Complete precision instruments","Inspect quality and assembly"],"msActions":["Look at the structure of precision instruments at a machinery fair or science museum","Build a small assembly kit or model to improve your accuracy","Research how a microscope or camera is built and draw it"]},
  "cn-125": {"name":"CAD Drafter","summary":"Draws detailed plans for buildings, machines, and electrical products using computer design software.","tasks":["Create CAD drawings","Make design sketches and calculations","Check drawings"],"msActions":["Join a CAD experience program","Measure your classroom or room with a ruler and draw it as a floor plan","Try simple 3D modeling software"]},
  "cn-126": {"name":"General Laborer","summary":"Moves, sorts, and packs products and materials, or assembles parts by hand.","tasks":["Carry materials and products","Sort and stack","Pack and do simple assembly"],"msActions":["Help carry and arrange things at a school or neighborhood event","Watch videos to learn about work at logistics centers and construction sites","Research how to lift heavy objects safely"]},
  "cn-127": {"name":"Foundry Worker","summary":"Melts metal, pours it into a mold, and lets it cool to make products in the shape needed.","tasks":["Review drawings and work orders","Make patterns and pour molten metal","Inspect size and defects"],"msActions":["Find out about metal fairs or steel mill tour programs","Watch videos on how metal melts and hardens","Make a mold from clay or plaster and press out a shape"]},
