  "cn-253": {"name":"Office Assistant","summary":"Helps office staff by organizing documents and entering data into computers.","tasks":["Deliver and organize documents","Tally and copy data","Enter data and fix errors"],"msActions":["Make simple tables and documents with word processing and spreadsheet programs","Sort and organize materials for your class or club","Look into the public servant career mentoring program at a local career experience support center"]},
