  "cn-10076": {"name":"Mobile App Developer","summary":"Plans, develops, and fixes apps used on smartphones and tablets.","tasks":["Plan and develop apps","Review technology for each operating system","Train users and coordinate with systems"],"msActions":["Make a small app or game with block coding or simple programming","Find what is inconvenient in an app you use often and write ideas to improve it","Look up career experience programs for mobile app developers"]},
