  "cn-10080": {"name":"Fair Trade Specialist","summary":"Helps import and sell products made in developing countries so they are traded fairly, and teaches people about fair trade.","tasks":["Import, distribute, and sell products","Train local producers","Run fair trade education programs"],"msActions":["Look for fair trade products and read what is written on their packaging","Research where and how the things you buy are made","Look up career experience programs about fair trade"]},
  "cn-10101": {"name":"Metaverse Creator","summary":"Designs and builds items, buildings, and maps in metaverse virtual spaces.","tasks":["Make and sell items","Design buildings and maps in virtual spaces","3D modeling"],"msActions":["Be active on a metaverse platform and look at how its items and spaces are decorated","Make a simple object with 3D graphics software","Draw a building you like and imagine moving it into a virtual space"]},
  "cn-10102": {"name":"Emotion Recognition Technology Specialist","summary":"Develops sensors and recognition technology so computers can detect human emotions.","tasks":["Develop emotion recognition technology","Develop wired and wireless sensor technology","Apply the technology to wearable devices"],"msActions":["Learn an easy programming language such as Python","Try out how artificial intelligence tells photos or voices apart","Observe and record how your feelings show in your face and voice"]},
  "cn-10103": {"name":"Personal Mobility Developer","summary":"Researches the power units and design of one-person vehicles such as electric scooters and improves their performance.","tasks":["Research and design vehicles","Design power units and parts","Evaluate and improve performance"],"msActions":["Research how electric scooters and electric bicycles work and draw their structure","Build a small model car with a battery and a motor and compare speeds","Sketch a new vehicle you would like to ride and add a description"]},
