  "cn-10105": {"name":"Solar Power Researcher and Developer","summary":"Researches and develops solar cells that make electricity from sunlight, power generation equipment, and production processes.","tasks":["Develop solar cells and modules","Design production process equipment","Research power system efficiency"],"msActions":["Assemble a solar cell kit to learn how light turns into electricity","Find solar panels on schools or buildings in your neighborhood and organize photos of them","Visit a renewable energy exhibition hall or a solar power plant"]},
