  "cn-10118": {"name":"Data Labeler","summary":"Adds information tags (labels) to data such as photos, text, videos, and sounds so that artificial intelligence can learn from them.","tasks":["Enter labels on data","Mark objects in images and videos","Complete the assigned workload"],"msActions":["Build your observation skills by sorting objects around you by their features","Learn how to use a word processor or spreadsheet program","Try a simple task on a data labeling platform"]},
